import { BQ79600PWRQ1 } from "./imports/BQ79600PWRQ1"
import { ALT4532M_171_T001 } from "./imports/ALT4532M_171_T001"
import { PS102J3F1504 } from "./imports/PS102J3F1504"

export const CommunicationBridge = () => (
  <group>
    {/* Bridge ASIC */}
    <BQ79600PWRQ1
      name="U4"
      pcbX={0}
      pcbY={0}
    />

    {/* Power Decoupling Caps */}
    {/* BAT Bypass Cap */}
    <capacitor
      name="C27"
      capacitance="0.1uF"
      footprint="0603"
      pcbX={-10}
      pcbY={10}
    />
    {/* VIO Bypass Cap */}
    <capacitor
      name="C24"
      capacitance="0.1uF"
      footprint="0603"
      pcbX={-10}
      pcbY={5}
    />
    {/* CVDD Capacitor */}
    <capacitor
      name="C25"
      capacitance="1uF"
      footprint="0603"
      pcbX={-10}
      pcbY={0}
    />
    {/* DVDD Capacitor */}
    <capacitor
      name="C26"
      capacitance="1uF"
      footprint="0603"
      pcbX={-10}
      pcbY={-5}
    />

    {/* Isolation Transformers and Caps */}
    {/* COMH Channel */}
    <ALT4532M_171_T001
      name="T1"
      pcbX={15}
      pcbY={10}
    />
    <PS102J3F1504
      name="C33"
      pcbX={10}
      pcbY={12}
    />
    <PS102J3F1504
      name="C34"
      pcbX={10}
      pcbY={8}
    />
    <resistor
      name="R40"
      resistance="100"
      footprint="0603"
      pcbX={20}
      pcbY={10}
    />

    {/* COML Channel */}
    <ALT4532M_171_T001
      name="T2"
      pcbX={15}
      pcbY={-10}
    />
    <PS102J3F1504
      name="C35"
      pcbX={10}
      pcbY={-8}
    />
    <PS102J3F1504
      name="C36"
      pcbX={10}
      pcbY={-12}
    />
    <resistor
      name="R41"
      resistance="100"
      footprint="0603"
      pcbX={20}
      pcbY={-10}
    />

    {/* Host Interface Series Resistors */}
    <resistor name="R33" resistance="22" footprint="0603" pcbX={-5} pcbY={5} /> {/* MOSI */}
    <resistor name="R34" resistance="22" footprint="0603" pcbX={-5} pcbY={2} /> {/* MISO */}
    <resistor name="R35" resistance="22" footprint="0603" pcbX={-5} pcbY={-1} /> {/* SCLK */}
    <resistor name="R36" resistance="22" footprint="0603" pcbX={-5} pcbY={-4} /> {/* nCS */}

    {/* INH Pull-down */}
    <resistor name="R37" resistance="100k" footprint="0603" pcbX={-5} pcbY={-10} />

    {/* NFAULT Pull-up */}
    <resistor name="R38" resistance="10k" footprint="0603" pcbX={-15} pcbY={5} />

    {/* SPI/UART Mode Strapping - Pulled to VIO for SPI mode */}
    <resistor name="R39" resistance="100k" footprint="0603" pcbX={-15} pcbY={10} />

    {/* Connections */}

    {/* Power and Ground */}
    <net name="BAT" pins={[".U4 > BAT", ".C27 > pin1"]} />
    <net name="GND" pins={[".U4 > GND", ".C27 > pin2", ".C24 > pin2", ".C25 > pin2", ".C26 > pin2", ".R37 > pin1"]} />
    <net name="VIO" pins={[".U4 > VIO", ".C24 > pin1", ".R38 > pin2", ".R39 > pin1"]} />
    <net name="CVDD" pins={[".U4 > CVDD", ".C25 > pin1"]} />
    <net name="DVDD" pins={[".U4 > DVDD", ".C26 > pin1"]} />

    {/* SPI Host Interface */}
    <net name="MOSI_U4" pins={[".U4 > pin4", ".R33 > pin1"]} />
    <net name="MISO_U4" pins={[".U4 > pin5", ".R34 > pin1"]} />
    <net name="SCLK_U4" pins={[".U4 > pin6", ".R35 > pin1"]} />
    <net name="nCS_U4" pins={[".U4 > pin7", ".R36 > pin1"]} />

    <net name="NFAULT" pins={[".U4 > NFAULT", ".R38 > pin1"]} />
    <net name="INH" pins={[".U4 > INH", ".R37 > pin2"]} />

    {/* Mode Selection - SPI Mode (High) */}
    <net name="nUART_SPI" pins={[".U4 > pin8", ".R39 > pin2"]} />

    {/* COMH Isolated Interface */}
    <net name="COMHP_CAP" pins={[".U4 > COMHP", ".C33 > pin1"]} />
    <net name="COMHN_CAP" pins={[".U4 > COMHN", ".C34 > pin1"]} />
    <net name="COMHP_T1" pins={[".C33 > pin2", ".T1 > pin1"]} />
    <net name="COMHN_T1" pins={[".C34 > pin2", ".T1 > pin2"]} />
    <net name="COMHP_ISO" pins={[".T1 > pin6", ".R40 > pin1"]} />
    <net name="COMHN_ISO" pins={[".T1 > pin5", ".R40 > pin2"]} />

    {/* COML Isolated Interface */}
    <net name="COMLP_CAP" pins={[".U4 > COMLP", ".C35 > pin1"]} />
    <net name="COMLN_CAP" pins={[".U4 > COMLN", ".C36 > pin1"]} />
    <net name="COMLP_T2" pins={[".C35 > pin2", ".T2 > pin1"]} />
    <net name="COMLN_T2" pins={[".C36 > pin2", ".T2 > pin2"]} />
    <net name="COMLP_ISO" pins={[".T2 > pin6", ".R41 > pin1"]} />
    <net name="COMLN_ISO" pins={[".T2 > pin5", ".R41 > pin2"]} />

    {/* Boundary Port Mapping */}
    {/* Ports will be connected to the nets */}
    <port name="P1_1_COMHP" net="COMHP_ISO" />
    <port name="P1_1_COMHN" net="COMHN_ISO" />
    <port name="P1_2_COMLP" net="COMLP_ISO" />
    <port name="P1_2_COMLN" net="COMLN_ISO" />
    <port name="P1_3_CVDD" net="CVDD" />

    <port name="P2_1_BAT" net="BAT" />
    <port name="P2_2_VIO" net="VIO" />
    <port name="P2_3_GND" net="GND" />
    <port name="P2_4_SCLK" net="SCLK_MCU" />
    <port name="P2_5_nCS" net="nCS_MCU" />
    <port name="P2_6_MOSI" net="MOSI_MCU" />
    <port name="P2_7_MISO" net="MISO_MCU" />
    <port name="P2_8_nUART_SPI" net="nUART_SPI" />
    <port name="P2_9_NFAULT" net="NFAULT" />
    <port name="P2_10_INH" net="INH" />
    <port name="P2_11_DVDD" net="DVDD" />

    {/* MCU side nets */}
    <net name="SCLK_MCU" pins={[".R35 > pin2"]} />
    <net name="nCS_MCU" pins={[".R36 > pin2"]} />
    <net name="MOSI_MCU" pins={[".R33 > pin2"]} />
    <net name="MISO_MCU" pins={[".R34 > pin2"]} />

  </group>
)
